export const scripts: string[] = ["\n    let currentCoverCr = 1;\n\n    function setCover(crore, element) {\n      currentCoverCr = crore;\n      const buttons = document.querySelectorAll('.cover-btn');\n      buttons.forEach(btn => {\n        btn.classList.remove('bg-primary', 'text-on-primary', 'active');\n        btn.classList.add('bg-surface-pure', 'text-on-surface');\n      });\n      element.classList.remove('bg-surface-pure', 'text-on-surface');\n      element.classList.add('bg-primary', 'text-on-primary', 'active');\n      calculateQuote();\n    }\n\n    function calculateQuote() {\n      const ageSelect = document.getElementById('hlv-age');\n      const genderSelect = document.getElementById('hlv-gender');\n      const tobaccoChecked = document.querySelector('input[name=\"tobacco\"]:checked');\n      const incomeSelect = document.getElementById('hlv-income');\n      const tenureSelect = document.getElementById('hlv-tenure');\n      const displayElem = document.getElementById('display-premium');\n      const suggestedElem = document.getElementById('suggested-hlv-badge');\n\n      if (!ageSelect || !displayElem) return;\n\n      const age = parseInt(ageSelect.value, 10);\n      const isFemale = genderSelect.value === 'female';\n      const isSmoker = tobaccoChecked ? tobaccoChecked.value === 'yes' : false;\n      const incomeLakhs = parseInt(incomeSelect.value, 10);\n\n      // Dynamic suggested HLV recommendation\n      if (incomeLakhs <= 10) {\n        suggestedElem.textContent = 'Recommended: \u20b91.5 Cr';\n      } else if (incomeLakhs <= 20) {\n        suggestedElem.textContent = 'Recommended: \u20b92.5 Cr';\n      } else if (incomeLakhs <= 35) {\n        suggestedElem.textContent = 'Recommended: \u20b94 Cr';\n      } else {\n        suggestedElem.textContent = 'Recommended: \u20b95 Cr+';\n      }\n\n      // Base formula calibrated to Indian market actuarial charts for \u20b91 Cr pure term\n      let baseRate = 540; // baseline 25y non-smoker\n      const ageDelta = Math.max(0, age - 25);\n      baseRate += (ageDelta * 28);\n\n      if (isSmoker) {\n        baseRate *= 1.65;\n      }\n      if (isFemale) {\n        baseRate *= 0.95;\n      }\n\n      // Multiply by Cover\n      let finalMonthly = baseRate * currentCoverCr;\n      finalMonthly = Math.round(finalMonthly / 10) * 10;\n\n      displayElem.textContent = '\u20b9' + finalMonthly.toLocaleString('en-IN');\n    }\n\n    function openWhatsAppQuote() {\n      const age = document.getElementById('hlv-age').value;\n      const smoker = document.querySelector('input[name=\"tobacco\"]:checked').value === 'yes' ? 'Smoker' : 'Non-Smoker';\n      const premiumText = document.getElementById('display-premium').textContent;\n      const message = `Hello Deeksha Insurance and Financial Services, I calculated a Term Life Shield quote: Cover: \u20b9${currentCoverCr} Cr, Age: ${age}, Status: ${smoker}. Indicative: ${premiumText}/month. Please help me compare the best plans.`;\n      window.open(`https://wa.me/916374423164?text=${encodeURIComponent(message)}`, '_blank');\n    }\n\n    function toggleFaq(button) {\n      const content = button.nextElementSibling;\n      const icon = button.querySelector('.material-symbols-outlined');\n      const isHidden = content.classList.contains('hidden');\n      \n      if (isHidden) {\n        content.classList.remove('hidden');\n        icon.style.transform = 'rotate(180deg)';\n      } else {\n        content.classList.add('hidden');\n        icon.style.transform = 'rotate(0deg)';\n      }\n    }\n\n    // Trigger initial calculation on page load\n    calculateQuote();\n  "];
